BEGIN;

CREATE TABLE ai_conversations (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL REFERENCES tenants(id),
  actor_id uuid NOT NULL REFERENCES app_users(id),
  state jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ai_conversations_actor_idx ON ai_conversations (tenant_id, actor_id, updated_at);

-- Never compare vectors generated by different models in the same search.
ALTER TABLE knowledge_documents ADD COLUMN embedding_model text NOT NULL DEFAULT 'hash-v1-384';
CREATE INDEX knowledge_documents_model_idx ON knowledge_documents (tenant_id, embedding_model)
  WHERE deleted_at IS NULL;

COMMIT;
